import { internal } from "!/_generated/api";
import { Doc } from "!/_generated/dataModel";
import { internalMutation, internalQuery, query } from "!/_generated/server";
import { v } from "convex/values";
import { allConvexInstances } from "./aggregates/admin_aggregates";

export const save = internalMutation({
  args: {
    projectId: v.id("project"),
    convexProjectId: v.number(),
    devDeploymentName: v.string(),
    prodDeploymentName: v.union(v.string(), v.null()),
    upsert: v.optional(v.boolean()),
  },
  handler: async (ctx, args) => {
    const matchingRecord = await ctx.runQuery(internal.convex_instance.get, {
      projectId: args.projectId,
    });

    // if the record exists and we're not upserting, throw an error
    if (matchingRecord && !args.upsert) {
      throw new Error("Convex instance already exists, cannot re-save");
    }

    // If upserting and record exists, update it
    if (matchingRecord && args.upsert) {
      const oldDoc = matchingRecord;
      await ctx.db.patch(matchingRecord._id, {
        convexProjectId: args.convexProjectId,
        devDeploymentName: args.devDeploymentName,
        prodDeploymentName: args.prodDeploymentName,
      });
      const newDoc = (await ctx.db.get(
        matchingRecord._id,
      )) as Doc<"project_convex_instance"> | null;
      if (newDoc) {
        // Update aggregate with the replacement
        await allConvexInstances.replace(ctx, oldDoc, newDoc);
      }
      return;
    }

    // Otherwise, insert a new record
    const instanceId = await ctx.db.insert("project_convex_instance", {
      projectId: args.projectId,
      convexProjectId: args.convexProjectId,
      devDeploymentName: args.devDeploymentName,
      prodDeploymentName: args.prodDeploymentName,
    });

    // Update aggregates for new convex instance
    const newInstance = await ctx.db.get(instanceId);
    if (newInstance) {
      await allConvexInstances.insert(ctx, newInstance);
    }
  },
});

export const get = internalQuery({
  args: {
    projectId: v.id("project"),
  },
  handler: async (
    ctx,
    args,
  ): Promise<Doc<"project_convex_instance"> | null> => {
    return await ctx.db
      .query("project_convex_instance")
      .withIndex("by_project", (q) => q.eq("projectId", args.projectId))
      .first();
  },
});

// Internal cacheable version - accepts semanticIdentifier directly
export const lookupInternal = internalQuery({
  args: {
    semanticIdentifier: v.string(),
  },
  handler: async (
    ctx,
    args,
  ): Promise<Doc<"project_convex_instance"> | null> => {
    const matchingProject = await ctx.db
      .query("project")
      .withIndex("by_semantic_identifier", (q) =>
        q.eq("semantic_identifier", args.semanticIdentifier),
      )
      .unique();

    if (!matchingProject) {
      return null;
    }

    return await ctx.db
      .query("project_convex_instance")
      .withIndex("by_project", (q) => q.eq("projectId", matchingProject._id))
      .first();
  },
});

export const lookup = query({
  args: {
    semanticIdentifier: v.optional(v.string()),
  },
  handler: async (
    ctx,
    args,
  ): Promise<Doc<"project_convex_instance"> | null> => {
    if (!args.semanticIdentifier) {
      return null;
    }

    // Delegate to internal cached version
    return await ctx.runQuery(internal.convex_instance.lookupInternal, {
      semanticIdentifier: args.semanticIdentifier,
    });
  },
});

