export const updateProdDeploymentName = internalMutation({
  args: {
    projectId: v.id("project"),
    prodDeploymentName: v.string(),
  },
  handler: async (ctx, args) => {
    const matchingRecord = await ctx.runQuery(internal.convex_instance.get, {
      projectId: args.projectId,
    });

    if (!matchingRecord) {
      throw new Error(
        "Convex instance not found for project " + args.projectId,
      );
    }

    await ctx.db.patch(matchingRecord._id, {
      prodDeploymentName: args.prodDeploymentName,
    });
  },
});

export const updateLogStreamIds = internalMutation({
  args: {
    projectId: v.id("project"),
    devLogStreamId: v.optional(v.string()),
    prodLogStreamId: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    const matchingRecord = await ctx.runQuery(internal.convex_instance.get, {
      projectId: args.projectId,
    });

    if (!matchingRecord) {
      throw new Error(
        "Convex instance not found for project " + args.projectId,
      );
    }

    const updateData: {
      devLogStreamId?: string;
      prodLogStreamId?: string;
    } = {};

    if (args.devLogStreamId !== undefined) {
      updateData.devLogStreamId = args.devLogStreamId;
    }
    if (args.prodLogStreamId !== undefined) {
      updateData.prodLogStreamId = args.prodLogStreamId;
    }

    await ctx.db.patch(matchingRecord._id, updateData);
  },
});
